makePencil('loose-pencil-right', [1.76, 0.79, 1.31], [2.62, 0.79, 1.17], M.darkWood, 0.022);
makePencil('pen-on-open-notebook', [-0.17, 0.84, 2.03], [0.40, 0.84, 1.92], M.pen, 0.032);

const LOOP = 1500;
const leanKeys = [[0, 0], [200, 0.03], [400, 0.16], [600, 0.58], [800, 0.82], [1000, 1], [1200, 1], [1400, 1], [1500, 0]];
const nuzzleKeys = [[0, 0], [200, 0.08], [400, 0.25], [600, 0.75], [800, 0.95], [1000, 1], [1200, 1], [1400, 1], [1500, 0]];
const retreatKeys = [[0, 0], [200, 0], [400, 0.10], [600, 0.72], [800, 0.93], [1000, 1], [1200, 1], [1400, 1], [1500, 0]];
const patYKeys = [[0, 0], [200, 0.35], [400, 0.65], [600, 1], [800, 0.82], [1000, 0.50], [1200, 0.30], [1400, 0.22], [1500, 0]];
const patXKeys = [[0, 0], [200, 0.25], [400, 0.55], [600, 1], [800, 1], [1000, 0.95], [1200, 0.90], [1400, 0.90], [1500, 0]];
const mouthKeys = [[0, 0], [200, 0], [400, 0.05], [600, 0.80], [800, 1], [1000, 1], [1200, 1], [1400, 1], [1500, 0]];
const dipKeys = [[0, 0], [200, 0.20], [400, 1], [600, 0.50], [800, 0], [1000, 0], [1200, 0], [1400, 0], [1500, 0]];

function sample(keys, t) {
  if (t <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) {
    if (t <= keys[i][0]) {
      const a = keys[i - 1], b = keys[i];
      let u = (t - a[0]) / (b[0] - a[0]);
      u = u * u * (3 - 2 * u);
      return THREE.MathUtils.lerp(a[1], b[1], u);
    }
  }
  return keys[keys.length - 1][1];
}

function render(t) {
  const phase = ((t % LOOP) + LOOP) % LOOP;
  const lean = sample(leanKeys, phase);
  const nuzzle = sample(nuzzleKeys, phase);
  const retreat = sample(retreatKeys, phase);
